POU.Declaration:
FUNCTION_BLOCK FB_EpsonAdsControl EXTENDS FB_Base
VAR_INPUT
END_VAR
VAR_OUTPUT
END_VAR
VAR
    {attribute 'TcHmiSymbol.AddSymbol'}
    stHmi                   : ST_EpsonAdsControlHmi;        // HMI interface

    stProperties            : ST_EpsonAdsControlProperties; // properties
    stAlarms                : ST_EpsonAdsControlAlarms;     // alarms (eventlogger)

    // Timers & watchdogs
    fbAckTimer              : TON;  // wait for AcceptedSequence
    fbCmdTimer              : TON;  // wait for DoneSequence / ErrorSequence
    fbHeartbeatTimer        : TON;  // IPC heartbeat supervision
    nLastHeartbeat          : UDINT := 0;

    nLastSequence           : UDINT := 0;   // counter for unique command sequences
    nLastReactionSequence   : UDINT := 0;   // counter for user reaction backchannel
    nLastRecipeAckSequence  : UDINT := 0;   // last answered press recipe request
    nLastGrantedMask        : DWORD := 0;   // GrantSequence edge detection

    // one-shot command request, set by RequestCommand() / ResetError()
    bReqCommand             : BOOL;
    stReqCmd                : ST_EpsonCmd;

    // CONFIG structure
    {attribute 'TcPersistent'}
    {attribute 'TcHmiSystemEng.Name' := ''}
    stConfig                : ST_EpsonAdsControlConfig;     // configuration
END_VAR
VAR CONSTANT
    nEPSON_INTERFACE_VERSION        : UINT := 2;    // must match C# IpcInterfaceVersion
END_VAR

Method.Declaration:
// Answer the active press recipe start request (backchannel, may be called
// during a running MoveWafer command). Writes AckSequence + Result to the GVL.
METHOD AnswerRecipeStart : BOOL
VAR_INPUT
    eResult                 : E_EpsonPressResult;
END_VAR

Implementation.ST:
IF GVL_EpsonADS.stIpcToPlc.Press.RecipeStartRequestSequence = 0 THEN
    F_SendMessage('RecipeStart not possible. No active request.', TcEventSeverity.Warning, THIS^.fbSourceInfo);
    AnswerRecipeStart := FALSE;
    RETURN;
END_IF

IF GVL_EpsonADS.stIpcToPlc.Press.RecipeStartRequestSequence = nLastRecipeAckSequence
   AND eResult = E_EpsonPressResult.Pending THEN
    // already acknowledged without a terminal result
    AnswerRecipeStart := FALSE;
    RETURN;
END_IF

GVL_EpsonADS.stPlcToIpc.External.Press.RecipeStartAckSequence := GVL_EpsonADS.stIpcToPlc.Press.RecipeStartRequestSequence;
GVL_EpsonADS.stPlcToIpc.External.Press.RecipeStartResult      := eResult;
nLastRecipeAckSequence := GVL_EpsonADS.stIpcToPlc.Press.RecipeStartRequestSequence;

AnswerRecipeStart := TRUE;

Method.Declaration:
// Answer the active user prompt (backchannel, may be called during a running
// command). Validates MessageId context and OptionsMask, then sends the reaction
// with a new UserReactionSequence.
METHOD AnswerUserPrompt : BOOL
VAR_INPUT
    eReaction               : E_EpsonUserReaction;
END_VAR

Implementation.ST:
IF NOT bEnable THEN
    F_SendMessage('UserReaction not possible. Function block disabled.', TcEventSeverity.Warning, THIS^.fbSourceInfo);
    AnswerUserPrompt := FALSE;
    RETURN;
END_IF

IF NOT GVL_EpsonADS.stIpcToPlc.UserPrompt.Active THEN
    F_SendMessage('UserReaction not possible. No active prompt.', TcEventSeverity.Warning, THIS^.fbSourceInfo);
    AnswerUserPrompt := FALSE;
    RETURN;
END_IF

IF eReaction = E_EpsonUserReaction.None
   OR (GVL_EpsonADS.stIpcToPlc.UserPrompt.OptionsMask AND TO_DWORD(eReaction)) = 0 THEN
    F_SendMessage('UserReaction not allowed by OptionsMask.', TcEventSeverity.Warning, THIS^.fbSourceInfo);
    AnswerUserPrompt := FALSE;
    RETURN;
END_IF

GVL_EpsonADS.stPlcToIpc.Cmd.UserMessageId := GVL_EpsonADS.stIpcToPlc.UserPrompt.MessageId;
GVL_EpsonADS.stPlcToIpc.Cmd.UserReaction  := eReaction;

nLastReactionSequence := nLastReactionSequence + 1;
IF nLastReactionSequence = 0 THEN
    nLastReactionSequence := 1;
END_IF
GVL_EpsonADS.stPlcToIpc.Cmd.UserReactionSequence := nLastReactionSequence;

AnswerUserPrompt := TRUE;

Method.Declaration:
// Send a command to the Epson IPC; accepted only while controlled by PLC logic
METHOD Command : BOOL
VAR_INPUT
    eCommand                : E_EpsonCommand;
    eSource                 : E_EpsonSource;
    nTargetSlot             : UINT;
    eRequiredTool           : E_EpsonTool;
    nMinPressDistanceUm     : DINT;
    bThinPlate              : BOOL;
    nCleanPosition          : UINT;
    nCleanStepCount         : UINT;
    eOutputIndex            : E_EpsonOutput;
    bOutputSet              : BOOL;
    bServiceEnable          : BOOL;
    stProtocol              : ST_EpsonProtocolCmd;
    bToolFromExternal       : BOOL;
    bOldToolToExternal      : BOOL;
    bUseExternalPutFallback : BOOL;
END_VAR

Implementation.ST:
stProperties.bDone := FALSE; // 1-cycle pulse

CASE stProperties.eState OF

    // ------------------------------------------------------------------------
    E_EpsonAdsControlState.IDLE:
    // ------------------------------------------------------------------------
        stProperties.bBusy := FALSE;
        fbAckTimer(IN := FALSE);
        fbCmdTimer(IN := FALSE);

        // resolve latched request
        IF bReqCommand THEN
            bReqCommand := FALSE;

            // new sequence number, 0 is not allowed
            nLastSequence := nLastSequence + 1;
            IF nLastSequence = 0 THEN
                nLastSequence := 1;
            END_IF
            stProperties.nActiveSequence := nLastSequence;
            stProperties.stLastCmd := stReqCmd;

            // write parameters to GVL (backchannel fields Cmd.User* are NOT touched)
            GVL_EpsonADS.stPlcToIpc.Cmd.Code                   := stReqCmd.Code;
            GVL_EpsonADS.stPlcToIpc.Cmd.Source                 := stReqCmd.Source;
            GVL_EpsonADS.stPlcToIpc.Cmd.TargetSlot             := stReqCmd.TargetSlot;
            GVL_EpsonADS.stPlcToIpc.Cmd.RequiredTool           := stReqCmd.RequiredTool;
            GVL_EpsonADS.stPlcToIpc.Cmd.MinPressDistanceUm     := stReqCmd.MinPressDistanceUm;
            GVL_EpsonADS.stPlcToIpc.Cmd.ThinPlate              := stReqCmd.ThinPlate;
            GVL_EpsonADS.stPlcToIpc.Cmd.CleanPosition          := stReqCmd.CleanPosition;
            GVL_EpsonADS.stPlcToIpc.Cmd.CleanStepCount         := stReqCmd.CleanStepCount;
            GVL_EpsonADS.stPlcToIpc.Cmd.OutputIndex            := stReqCmd.OutputIndex;
            GVL_EpsonADS.stPlcToIpc.Cmd.OutputSet              := stReqCmd.OutputSet;
            GVL_EpsonADS.stPlcToIpc.Cmd.ServiceEnable          := stReqCmd.ServiceEnable;
            GVL_EpsonADS.stPlcToIpc.Cmd.Protocol               := stReqCmd.Protocol;
            GVL_EpsonADS.stPlcToIpc.Cmd.ToolFromExternal       := stReqCmd.ToolFromExternal;
            GVL_EpsonADS.stPlcToIpc.Cmd.OldToolToExternal      := stReqCmd.OldToolToExternal;
            GVL_EpsonADS.stPlcToIpc.Cmd.UseExternalPutFallback := stReqCmd.UseExternalPutFallback;

            stProperties.eState := E_EpsonAdsControlState.SEND_COMMAND;
        END_IF

    // ------------------------------------------------------------------------
    E_EpsonAdsControlState.SEND_COMMAND:
    // ------------------------------------------------------------------------
        stProperties.bBusy := TRUE;

        // activate parameters in GVL
        GVL_EpsonADS.stPlcToIpc.Cmd.Sequence := stProperties.nActiveSequence;
        GVL_EpsonADS.stPlcToIpc.Cmd.Valid := TRUE;

        stProperties.eState := E_EpsonAdsControlState.WAIT_ACCEPT;

    // ------------------------------------------------------------------------
    E_EpsonAdsControlState.WAIT_ACCEPT:
    // ------------------------------------------------------------------------
        stProperties.bBusy := TRUE;

        // check 1: IPC rejected the command already (validation failure)
        IF GVL_EpsonADS.stIpcToPlc.Cmd.ErrorSequence = stProperties.nActiveSequence THEN
            stProperties.bBusy := FALSE;
            stProperties.nErrorSequence := stProperties.nActiveSequence;
            GVL_EpsonADS.stPlcToIpc.Cmd.Valid := FALSE;
            SetError(nErrorCode := GVL_EpsonADS.stIpcToPlc.Error.Code,
                     sErrorText := GVL_EpsonADS.stIpcToPlc.Error.Text);

        // check 2: IPC accepted the sequence?
        ELSIF GVL_EpsonADS.stIpcToPlc.Cmd.AcceptedSequence = stProperties.nActiveSequence THEN
            fbAckTimer(IN := FALSE);
            fbCmdTimer(IN := FALSE);
            stProperties.eState := E_EpsonAdsControlState.WAIT_COMPLETION;
        ELSE
            fbAckTimer(IN := TRUE, PT := UDINT_TO_TIME(stConfig.nTimeoutAckMs));
            IF fbAckTimer.Q THEN
                bAlarmTimeoutAck := TRUE;
                SetError(nErrorCode := 8001, sErrorText := 'Timeout: IPC did not acknowledge the command (AcceptedSequence)');
            END_IF
        END_IF

    // ------------------------------------------------------------------------
    E_EpsonAdsControlState.WAIT_COMPLETION:
    // ------------------------------------------------------------------------
        stProperties.bBusy := TRUE;

        // check 1: completed ok?
        IF GVL_EpsonADS.stIpcToPlc.Cmd.DoneSequence = stProperties.nActiveSequence THEN
            stProperties.bDone := TRUE;
            stProperties.bBusy := FALSE;
            stProperties.nDoneSequence := stProperties.nActiveSequence;
            GVL_EpsonADS.stPlcToIpc.Cmd.Valid := FALSE;
            stProperties.eState := E_EpsonAdsControlState.IDLE;

            // a successfully executed ResetError clears the latched PLC-side error
            IF stProperties.stLastCmd.Code = E_EpsonCommand.ResetError THEN
                stProperties.nErrorCode := 0;
                stProperties.sErrorText := '';
            END_IF

        // check 2: completed with error?
        ELSIF GVL_EpsonADS.stIpcToPlc.Cmd.ErrorSequence = stProperties.nActiveSequence THEN
            stProperties.bBusy := FALSE;
            stProperties.nErrorSequence := stProperties.nActiveSequence;
            GVL_EpsonADS.stPlcToIpc.Cmd.Valid := FALSE;
            SetError(nErrorCode := GVL_EpsonADS.stIpcToPlc.Error.Code,
                     sErrorText := GVL_EpsonADS.stIpcToPlc.Error.Text);

        // check 3: command timeout
        ELSE
            fbCmdTimer(IN := TRUE, PT := UDINT_TO_TIME(stConfig.nTimeoutCmdMs));
            IF fbCmdTimer.Q THEN
                bAlarmTimeoutCmd := TRUE;
                SetError(nErrorCode := 8002, sErrorText := 'Timeout: command execution on IPC exceeded');
            END_IF
        END_IF

    // ------------------------------------------------------------------------
    E_EpsonAdsControlState.ERROR:
    // ------------------------------------------------------------------------
        stProperties.bBusy := FALSE;
        GVL_EpsonADS.stPlcToIpc.Cmd.Valid := FALSE;

        // IPC keeps Error.Active latched (contract v2). Remains in error state
        // until ResetError() issued the ResetError command (110); that order is
        // dispatched through the regular postbox by leaving ERROR for IDLE.
        IF bReqCommand THEN
            IF stReqCmd.Code = E_EpsonCommand.ResetError THEN
                stProperties.eState := E_EpsonAdsControlState.IDLE;
            ELSE
                // stale non-reset request cannot run in ERROR; drop it so
                // ResetError() is not blocked by a pending request
                bReqCommand := FALSE;
            END_IF
        END_IF

END_CASE

EvaluateCommand := TRUE;

// publish own interface version
GVL_EpsonADS.stPlcToIpc.InterfaceVersion := nEPSON_INTERFACE_VERSION;

// heartbeat monitoring
IF GVL_EpsonADS.stIpcToPlc.Heartbeat <> nLastHeartbeat THEN
    nLastHeartbeat := GVL_EpsonADS.stIpcToPlc.Heartbeat;
    fbHeartbeatTimer(IN := FALSE);
    stProperties.bHeartbeatOk := TRUE;
ELSE
    fbHeartbeatTimer(IN := TRUE, PT := UDINT_TO_TIME(stConfig.nTimeoutHeartbeatMs));
    IF fbHeartbeatTimer.Q THEN
        stProperties.bHeartbeatOk := FALSE;
    END_IF
END_IF

bAlarmHeartbeatLost := NOT stProperties.bHeartbeatOk;

// IPC connection channels (Phase 3)
stProperties.bAdsConnected             := GVL_EpsonADS.stIpcToPlc.AdsConnected;
stProperties.bStationChannelConnected  := GVL_EpsonADS.stIpcToPlc.StationChannelConnected;
stProperties.bRemoteControlConnected   := GVL_EpsonADS.stIpcToPlc.RemoteControlConnected;

// heartbeat or ADS loss during an active command aborts the order
IF (NOT stProperties.bHeartbeatOk OR NOT stProperties.bAdsConnected)
   AND (stProperties.eState = E_EpsonAdsControlState.WAIT_ACCEPT
     OR stProperties.eState = E_EpsonAdsControlState.WAIT_COMPLETION) THEN
    IF NOT stProperties.bAdsConnected THEN
        SetError(nErrorCode := 8004, sErrorText := 'IPC ADS connection lost during active command');
    ELSE
        SetError(nErrorCode := 8003, sErrorText := 'Timeout: IPC heartbeat lost during active command');
    END_IF
END_IF

// interface version check (latched, blocks command handling)
// only evaluated while the IPC is actually present: at PLC start the IPC has not
// published its snapshot yet (version field = 0) and must not latch an error
bAlarmVersionMismatch := stProperties.bHeartbeatOk
    AND GVL_EpsonADS.stIpcToPlc.InterfaceVersion <> nEPSON_INTERFACE_VERSION;
IF bAlarmVersionMismatch AND stProperties.eState <> E_EpsonAdsControlState.ERROR THEN
    SetError(nErrorCode := 9001, sErrorText := 'Interface version mismatch between PLC and Epson IPC');
END_IF

// command error alarm follows the ERROR state, cleared via ResetError() command
bAlarmCommandError := (stProperties.eState = E_EpsonAdsControlState.ERROR);

EvaluateLink := TRUE;

SUPER^.Init();

stProperties.eState       := E_EpsonAdsControlState.IDLE;
stProperties.bBusy        := FALSE;
stProperties.bDone        := FALSE;
stProperties.bHeartbeatOk := FALSE;
stProperties.nErrorCode   := 0;
stProperties.sErrorText   := '';

bReqCommand := FALSE;
nLastReactionSequence  := 0;
nLastRecipeAckSequence := 0;
nLastGrantedMask       := 0;

Method.Declaration:
// Level based resource arbiter: grant only requested bits, honour IPC release
// requests (ReleaseMask), revoke everything on confirmed force release (recovery)
METHOD ManageLocks : BOOL
VAR_INPUT
    bTransferAllowed  : BOOL; // Transfer station free for Epson
    bPressAllowed     : BOOL; // WaferPress free for Epson
    bToolStatAllowed  : BOOL; // ToolStation free for Epson
    bGenmarkAllowed   : BOOL; // Genmark area free
    bStaeubliAllowed  : BOOL; // Staeubli area free
    bForceReleaseAllowed : BOOL; // recovery consent after local safety check
END_VAR
VAR
    dwRequests        : DWORD;
    dwGrants          : DWORD := 0;
    dwRelease         : DWORD;
END_VAR

Implementation.ST:
dwRequests := GVL_EpsonADS.stIpcToPlc.Lock.RequestMask;

// Bit 0: Wafer transfer station
IF (dwRequests AND 16#01) <> 0 AND bTransferAllowed THEN
    dwGrants := dwGrants OR 16#01;
END_IF

// Bit 1: WaferPress
IF (dwRequests AND 16#02) <> 0 AND bPressAllowed THEN
    dwGrants := dwGrants OR 16#02;
END_IF

// Bit 2: ToolStation
IF (dwRequests AND 16#04) <> 0 AND bToolStatAllowed THEN
    dwGrants := dwGrants OR 16#04;
END_IF

// Bit 3: Genmark area
IF (dwRequests AND 16#08) <> 0 AND bGenmarkAllowed THEN
    dwGrants := dwGrants OR 16#08;
END_IF

// Bit 4: Staeubli area
IF (dwRequests AND 16#10) <> 0 AND bStaeubliAllowed THEN
    dwGrants := dwGrants OR 16#10;
END_IF

// IPC-requested release: revoke and do not re-grant while the release is pending
dwRelease := GVL_EpsonADS.stIpcToPlc.Lock.ReleaseMask;
dwGrants := dwGrants AND NOT dwRelease;

// Recovery: revoke everything, the IPC clears ForceReleaseRequest once
// GrantedMask is empty (contract v2)
IF GVL_EpsonADS.stIpcToPlc.Lock.ForceReleaseRequest AND bForceReleaseAllowed THEN
    dwGrants := 0;
END_IF

// GrantSequence: increment on every change of the granted bits
IF dwGrants <> nLastGrantedMask THEN
    GVL_EpsonADS.stPlcToIpc.Lock.GrantSequence := GVL_EpsonADS.stPlcToIpc.Lock.GrantSequence + 1;
    IF GVL_EpsonADS.stPlcToIpc.Lock.GrantSequence = 0 THEN
        GVL_EpsonADS.stPlcToIpc.Lock.GrantSequence := 1;
    END_IF
    nLastGrantedMask := dwGrants;
END_IF

// write granted locks to GVL and properties
GVL_EpsonADS.stPlcToIpc.Lock.GrantedMask := dwGrants;
stProperties.dwRequestMask := dwRequests;
stProperties.dwGrantedMask := dwGrants;

ManageLocks := TRUE;

Method.Declaration:
// Request to send a command to the IPC; rejected immediately if disabled,
// link down, busy or in error state. Evaluated in EvaluateCommand().
METHOD PRIVATE RequestCommand : BOOL
VAR_INPUT
    eCommand                : E_EpsonCommand;
    eSource                 : E_EpsonSource;
    nTargetSlot             : UINT;
    eRequiredTool           : E_EpsonTool;
    nMinPressDistanceUm     : DINT;
    bThinPlate              : BOOL;
    nCleanPosition          : UINT;
    nCleanStepCount         : UINT;
    eOutputIndex            : E_EpsonOutput;
    bOutputSet              : BOOL;
    bServiceEnable          : BOOL;
    stProtocol              : ST_EpsonProtocolCmd;
    bToolFromExternal       : BOOL;
    bOldToolToExternal      : BOOL;
    bUseExternalPutFallback : BOOL;
END_VAR

Implementation.ST:
// Check Enable
IF NOT bEnable THEN
    F_SendMessage('Command not possible. Function block disabled.', TcEventSeverity.Warning, THIS^.fbSourceInfo);
    RequestCommand := FALSE;
    RETURN;
END_IF

// Check IPC link
IF NOT stProperties.bHeartbeatOk THEN
    F_SendMessage('Command not possible. IPC link not alive.', TcEventSeverity.Warning, THIS^.fbSourceInfo);
    RequestCommand := FALSE;
    RETURN;
END_IF

// Check state
IF stProperties.eState <> E_EpsonAdsControlState.IDLE THEN
    F_SendMessage('Command not possible. Block busy or in error state.', TcEventSeverity.Warning, THIS^.fbSourceInfo);
    RequestCommand := FALSE;
    RETURN;
END_IF

// IPC rejects commands while its error is latched (only ResetError passes)
IF GVL_EpsonADS.stIpcToPlc.Error.Active AND eCommand <> E_EpsonCommand.ResetError THEN
    F_SendMessage('Command not possible. IPC error latched, reset required.', TcEventSeverity.Warning, THIS^.fbSourceInfo);
    RequestCommand := FALSE;
    RETURN;
END_IF

stReqCmd.Sequence                := 0; // assigned in EvaluateCommand()
stReqCmd.Code                    := eCommand;
stReqCmd.Source                  := eSource;
stReqCmd.TargetSlot              := nTargetSlot;
stReqCmd.RequiredTool            := eRequiredTool;
stReqCmd.MinPressDistanceUm      := nMinPressDistanceUm;
stReqCmd.ThinPlate               := bThinPlate;
stReqCmd.CleanPosition           := nCleanPosition;
stReqCmd.CleanStepCount          := nCleanStepCount;
stReqCmd.OutputIndex             := eOutputIndex;
stReqCmd.OutputSet               := bOutputSet;
stReqCmd.ServiceEnable           := bServiceEnable;
stReqCmd.Protocol                := stProtocol;
stReqCmd.ToolFromExternal        := bToolFromExternal;
stReqCmd.OldToolToExternal       := bOldToolToExternal;
stReqCmd.UseExternalPutFallback  := bUseExternalPutFallback;
stReqCmd.Valid                   := FALSE;

bReqCommand := TRUE;

RequestCommand := TRUE;

Method.Declaration:
// Request the error reset as command 110 (contract v2): the IPC keeps
// Error.Active latched and clears it after the command completed successfully.
// The request runs through the normal mailbox handshake (EvaluateCommand).
METHOD ResetError : BOOL
VAR_INPUT
END_VAR

Implementation.ST:
IF stProperties.eState <> E_EpsonAdsControlState.ERROR THEN
    F_SendMessage('ResetError not possible. No error state active.', TcEventSeverity.Warning, THIS^.fbSourceInfo);
    ResetError := FALSE;
    RETURN;
END_IF

IF NOT bEnable OR NOT stProperties.bHeartbeatOk THEN
    F_SendMessage('ResetError not possible. Function block disabled or IPC link not alive.', TcEventSeverity.Warning, THIS^.fbSourceInfo);
    ResetError := FALSE;
    RETURN;
END_IF

IF bReqCommand THEN
    F_SendMessage('ResetError not possible. Command request pending.', TcEventSeverity.Warning, THIS^.fbSourceInfo);
    ResetError := FALSE;
    RETURN;
END_IF

stReqCmd.Code     := E_EpsonCommand.ResetError;
stReqCmd.Sequence := 0; // assigned in EvaluateCommand()
bReqCommand := TRUE;

ResetError := TRUE;

Method.Declaration:
// latch error info and switch to ERROR state (only on first occurrence)
METHOD PRIVATE SetError : BOOL
VAR_INPUT
    nErrorCode      : UINT;
    sErrorText      : STRING(255);
END_VAR

Implementation.ST:
IF stProperties.eState <> E_EpsonAdsControlState.ERROR THEN
    stProperties.nErrorCode := nErrorCode;
    stProperties.sErrorText := sErrorText;
    stProperties.eState     := E_EpsonAdsControlState.ERROR;
    F_SendMessage(
        sMessage := CONCAT(CONCAT(CONCAT(CONCAT('EPSON internal error ', stProperties.sErrorText), ' ['), TO_STRING(stProperties.nErrorCode)), ']'),
        eSeverity := TcEventSeverity.Error,
        iSourceInfo := THIS^.fbSourceInfo);
END_IF

SetError := TRUE;

Method.Declaration:
// Publish the external process state snapshot to the IPC (level driven).
// The press recipe backchannel fields are preserved.
METHOD UpdateExternalState : BOOL
VAR_INPUT
    bAutoMode         : BOOL;
    bSafetyPermissive : BOOL;
    stTransfer        : ST_EpsonTransferState;
    stPress           : ST_EpsonPressState;
    stToolStation     : ST_EpsonToolStationState;
    stGenmark         : ST_EpsonRobotState;
    stStaeubli        : ST_EpsonRobotState;
END_VAR
VAR
    stPressBuf        : ST_EpsonPressState;
END_VAR

Implementation.ST:
GVL_EpsonADS.stPlcToIpc.External.AutoMode         := bAutoMode;
GVL_EpsonADS.stPlcToIpc.External.SafetyPermissive := bSafetyPermissive;
GVL_EpsonADS.stPlcToIpc.External.Transfer         := stTransfer;
GVL_EpsonADS.stPlcToIpc.External.ToolStation      := stToolStation;
GVL_EpsonADS.stPlcToIpc.External.Genmark          := stGenmark;
GVL_EpsonADS.stPlcToIpc.External.Staeubli         := stStaeubli;

// preserve the press recipe backchannel while updating the process values
stPressBuf                          := GVL_EpsonADS.stPlcToIpc.External.Press;
stPressBuf.Ready                    := stPress.Ready;
stPressBuf.PlatePresent             := stPress.PlatePresent;
stPressBuf.ThinPlate                := stPress.ThinPlate;
stPressBuf.TargetSlotFree           := stPress.TargetSlotFree;
GVL_EpsonADS.stPlcToIpc.External.Press := stPressBuf;

GVL_EpsonADS.stPlcToIpc.External.Sequence := GVL_EpsonADS.stPlcToIpc.External.Sequence + 1;
GVL_EpsonADS.stPlcToIpc.External.Valid    := TRUE;

UpdateExternalState := TRUE;

// TRIGGERS
    fbTrigReset(CLK := stHmi.bCmdReset);
    fbTrigUserReaction(CLK := stHmi.bCmdUserReaction);

// BASE
    // STATUS
        stHmi.sName             := stBaseProperties.sName;
        stHmi.bEnable           := bEnable;
        stHmi.bError            := (stProperties.eState = E_EpsonAdsControlState.ERROR);
        stHmi.eControlSource    := eControlSource;

    // COMMAND
        // Reset
        IF fbTrigReset.Q THEN
            stHmi.bCmdReset := FALSE;
            IF eControlSource = E_ControlSource.HMI THEN
                ResetError();
            ELSE
                F_SendMessage('Command not accepted due to wrong ControlSource', TcEventSeverity.Warning, THIS^.fbSourceInfo);
            END_IF
        END_IF

        // User prompt answer
        IF fbTrigUserReaction.Q THEN
            stHmi.bCmdUserReaction := FALSE;
            IF eControlSource = E_ControlSource.HMI THEN
                AnswerUserPrompt(eReaction := stHmi.eCmdUserReaction);
            ELSE
                F_SendMessage('Command not accepted due to wrong ControlSource', TcEventSeverity.Warning, THIS^.fbSourceInfo);
            END_IF
        END_IF

// SPECIFIC
    // STATUS
        stHmi.eState            := stProperties.eState;
        stHmi.bBusy             := stProperties.bBusy;
        stHmi.bDone             := stProperties.bDone;
        stHmi.bHeartbeatOk      := stProperties.bHeartbeatOk;
        stHmi.nErrorCode        := stProperties.nErrorCode;
        stHmi.sErrorText        := stProperties.sErrorText;
        stHmi.nActiveSequence   := stProperties.nActiveSequence;
        stHmi.nDoneSequence     := stProperties.nDoneSequence;
        stHmi.nErrorSequence    := stProperties.nErrorSequence;
        stHmi.dwRequestMask     := stProperties.dwRequestMask;
        stHmi.dwGrantedMask     := stProperties.dwGrantedMask;

    // PHASE 3: progress, wafer flags, locks, IPC status, prompt, warning
        stHmi.eProgress            := stProperties.eProgress;
        stHmi.bWaferPicked         := stProperties.bWaferPicked;
        stHmi.bWaferPlaced         := stProperties.bWaferPlaced;
        stHmi.dwHeldMask           := stProperties.dwHeldMask;
        stHmi.dwReleaseMask        := stProperties.dwReleaseMask;
        stHmi.bForceReleaseRequest := stProperties.bForceReleaseRequest;
        stHmi.nGrantSequence       := stProperties.nGrantSequence;
        stHmi.bAdsConnected        := stProperties.bAdsConnected;
        stHmi.bStationChannelConnected := stProperties.bStationChannelConnected;
        stHmi.bRemoteControlConnected  := stProperties.bRemoteControlConnected;
        stHmi.eRobotState          := stProperties.eRobotState;
        stHmi.nCurrentToolType     := stProperties.nCurrentToolType;
        stHmi.stPrompt             := stProperties.stPrompt;
        stHmi.bWarning             := stProperties.bWarning;
        stHmi.sWarningText         := stProperties.sWarningText;

Method.Declaration:
// Copy the IPC status (progress, locks, robot state, prompt, warning)
// into the properties; called every cycle from Run()
METHOD PROTECTED UpdateStatus

Implementation.ST:
// Command progress and wafer flags (sequenzgebunden)
stProperties.eProgress    := GVL_EpsonADS.stIpcToPlc.Cmd.Progress;
stProperties.bWaferPicked := GVL_EpsonADS.stIpcToPlc.Cmd.WaferPicked;
stProperties.bWaferPlaced := GVL_EpsonADS.stIpcToPlc.Cmd.WaferPlaced;

// Lock lifecycle
